//! Procedural ambient sounds rendered to seamless in-memory loops.
//!
//! Everything is generated by this code (no third-party recordings, no
//! licensing questions). Each loop is rendered `LOOP_SECS + XFADE_SECS`
//! long and the overhang is equal-power cross-faded into the start, so the
//! buffer loops without a click.

use std::f32::consts::{PI, TAU};

pub const RATE: u32 = 44_100;
const LOOP_SECS: f32 = 30.0;
const XFADE_SECS: f32 = 2.0;

/// The procedural sounds on offer.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Synth {
    White,
    Pink,
    Brown,
    /// Binaural beat: carrier in the left ear, carrier + beat in the right.
    Binaural { carrier: u32, beat: u32 },
    Rain,
    Cafe,
}

/// Small deterministic PRNG (xorshift64*); quality is ample for noise.
struct Rng(u64);

impl Rng {
    fn next_u64(&mut self) -> u64 {
        self.0 ^= self.0 >> 12;
        self.0 ^= self.0 << 25;
        self.0 ^= self.0 >> 27;
        self.0.wrapping_mul(0x2545_F491_4F6C_DD1D)
    }
    /// Uniform in [0, 1).
    fn unit(&mut self) -> f32 {
        (self.next_u64() >> 40) as f32 / (1u64 << 24) as f32
    }
    /// Uniform in [-1, 1).
    fn bipolar(&mut self) -> f32 {
        self.unit() * 2.0 - 1.0
    }
    fn range(&mut self, lo: f32, hi: f32) -> f32 {
        lo + (hi - lo) * self.unit()
    }
}

/// Pink noise via Paul Kellet's economy filter (−3 dB/octave, ±0.5 dB).
#[derive(Default)]
struct Pink([f32; 3]);

impl Pink {
    fn next(&mut self, white: f32) -> f32 {
        let b = &mut self.0;
        b[0] = 0.99765 * b[0] + white * 0.0990460;
        b[1] = 0.96300 * b[1] + white * 0.2965164;
        b[2] = 0.57000 * b[2] + white * 1.0526913;
        (b[0] + b[1] + b[2] + white * 0.1848) * 0.2
    }
}

/// Brown (red) noise: leaky integrator of white noise (−6 dB/octave).
#[derive(Default)]
struct Brown(f32);

impl Brown {
    fn next(&mut self, white: f32) -> f32 {
        self.0 = (self.0 + 0.02 * white) * 0.997;
        self.0 * 3.5
    }
}

/// One-pole low-pass; `hp()` gives the complementary high-pass.
struct OnePole {
    a: f32,
    y: f32,
}

impl OnePole {
    fn new(cutoff_hz: f32) -> Self {
        Self { a: (-TAU * cutoff_hz / RATE as f32).exp(), y: 0.0 }
    }
    fn lp(&mut self, x: f32) -> f32 {
        self.y = x + self.a * (self.y - x);
        self.y
    }
    fn hp(&mut self, x: f32) -> f32 {
        x - self.lp(x)
    }
}

/// A short decaying sinusoid added into the stereo buffer (droplet/clink).
fn add_ping(buf: &mut [[f32; 2]], start: usize, freq: f32, tau_s: f32, amp: f32, pan: f32) {
    let len = ((tau_s * 6.0) * RATE as f32) as usize;
    let (gl, gr) = (((1.0 - pan) * PI / 4.0).cos() * amp, ((1.0 + pan) * PI / 4.0).sin() * amp);
    for i in 0..len.min(buf.len().saturating_sub(start)) {
        let t = i as f32 / RATE as f32;
        let v = (TAU * freq * t).sin() * (-t / tau_s).exp();
        buf[start + i][0] += v * gl;
        buf[start + i][1] += v * gr;
    }
}

/// Render `n` stereo frames of `synth` (before looping).
fn render_raw(synth: Synth, n: usize) -> Vec<[f32; 2]> {
    let mut rng = Rng(0x9E37_79B9_7F4A_7C15);
    let mut buf = vec![[0.0f32; 2]; n];
    let rate = RATE as f32;
    match synth {
        Synth::White => {
            for f in &mut buf {
                *f = [rng.bipolar() * 0.25, rng.bipolar() * 0.25];
            }
        }
        Synth::Pink | Synth::Brown => {
            let (mut pl, mut pr) = (Pink::default(), Pink::default());
            let (mut bl, mut br) = (Brown::default(), Brown::default());
            for f in &mut buf {
                let (wl, wr) = (rng.bipolar(), rng.bipolar());
                *f = if synth == Synth::Pink {
                    [pl.next(wl) * 0.5, pr.next(wr) * 0.5]
                } else {
                    [bl.next(wl) * 0.5, br.next(wr) * 0.5]
                };
            }
        }
        Synth::Binaural { carrier, beat } => {
            // Integer Hz over a whole-second loop = integer cycles, so the
            // tones are phase-continuous at the loop point.
            let (fl, fr) = (carrier as f32, (carrier + beat) as f32);
            let (mut pl, mut pr) = (Pink::default(), Pink::default());
            for (i, f) in buf.iter_mut().enumerate() {
                let t = i as f32 / rate;
                let bed = (pl.next(rng.bipolar()), pr.next(rng.bipolar()));
                *f = [(TAU * fl * t).sin() * 0.18 + bed.0 * 0.06, (TAU * fr * t).sin() * 0.18 + bed.1 * 0.06];
            }
        }
        Synth::Rain => {
            // Bed: high-passed pink "hiss" + low brown rumble, slowly swelling.
            let (mut pl, mut pr) = (Pink::default(), Pink::default());
            let (mut bl, mut br) = (Brown::default(), Brown::default());
            let (mut hl, mut hr) = (OnePole::new(500.0), OnePole::new(500.0));
            let (mut ll, mut lr) = (OnePole::new(300.0), OnePole::new(300.0));
            for (i, f) in buf.iter_mut().enumerate() {
                let t = i as f32 / rate;
                let swell = 0.85 + 0.15 * (TAU * t / 10.0).sin(); // 3 swells per 30 s loop
                let hiss = (hl.hp(pl.next(rng.bipolar())), hr.hp(pr.next(rng.bipolar())));
                let rumble = (ll.lp(bl.next(rng.bipolar())), lr.lp(br.next(rng.bipolar())));
                *f = [(hiss.0 * 0.55 + rumble.0 * 0.5) * swell, (hiss.1 * 0.55 + rumble.1 * 0.5) * swell];
            }
            // Droplets: Poisson arrivals (~35/s), short bright pings.
            let mut i = 0usize;
            loop {
                i += (-(rng.unit().max(1e-6)).ln() / 35.0 * rate) as usize;
                if i >= n {
                    break;
                }
                let (freq, tau) = (rng.range(1800.0, 5200.0), rng.range(0.002, 0.007));
                add_ping(&mut buf, i, freq, tau, rng.range(0.02, 0.12), rng.bipolar());
            }
        }
        Synth::Cafe => {
            // Murmur: band-limited brown noise with a syllable-rate envelope
            // made of a few incommensurate slow LFOs (sounds like many voices).
            let (mut bl, mut br) = (Brown::default(), Brown::default());
            let (mut ll, mut lr) = (OnePole::new(900.0), OnePole::new(900.0));
            let (mut hl, mut hr) = (OnePole::new(160.0), OnePole::new(160.0));
            let lfo: Vec<(f32, f32)> = (0..6).map(|_| (rng.range(1.5, 5.0), rng.range(0.0, TAU))).collect();
            for (i, f) in buf.iter_mut().enumerate() {
                let t = i as f32 / rate;
                let env = |k: usize| {
                    let s: f32 = lfo.iter().skip(k).step_by(2).map(|(hz, ph)| (TAU * hz * t + ph).sin()).sum();
                    0.6 + 0.4 * (s / 3.0)
                };
                let l = hl.hp(ll.lp(bl.next(rng.bipolar()))) * env(0);
                let r = hr.hp(lr.lp(br.next(rng.bipolar()))) * env(1);
                *f = [l * 1.6, r * 1.6];
            }
            // Cups and spoons: sparse inharmonic clinks.
            let mut i = 0usize;
            loop {
                i += (-(rng.unit().max(1e-6)).ln() / 0.5 * rate) as usize;
                if i >= n {
                    break;
                }
                let (f0, pan, amp) = (rng.range(2200.0, 4800.0), rng.bipolar(), rng.range(0.03, 0.09));
                for (ratio, gain) in [(1.0, 1.0), (2.76, 0.5), (5.40, 0.25)] {
                    add_ping(&mut buf, i, f0 * ratio, rng.range(0.06, 0.18), amp * gain, pan);
                }
            }
        }
    }
    buf
}

/// Render a seamless loop of `synth` as interleaved stereo f32 samples.
pub fn render_loop(synth: Synth) -> Vec<[f32; 2]> {
    let n = (LOOP_SECS * RATE as f32) as usize;
    let x = (XFADE_SECS * RATE as f32) as usize;
    let raw = render_raw(synth, n + x);
    let mut out = raw[..n].to_vec();
    // Equal-power cross-fade of the overhang into the head: sample n-1 is
    // followed by raw[n] in the source, which is exactly what out[0] now
    // starts from, so the wrap point is continuous.
    for i in 0..x {
        let p = i as f32 / x as f32;
        let (fade_in, fade_out) = ((p * PI / 2.0).sin(), (p * PI / 2.0).cos());
        for ch in 0..2 {
            out[i][ch] = raw[i][ch] * fade_in + raw[n + i][ch] * fade_out;
        }
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn loops_are_continuous_and_in_range() {
        for synth in [Synth::Pink, Synth::Brown, Synth::Rain, Synth::Cafe, Synth::Binaural { carrier: 200, beat: 40 }] {
            let s = render_loop(synth);
            assert_eq!(s.len(), (LOOP_SECS * RATE as f32) as usize);
            let peak = s.iter().flatten().fold(0.0f32, |m, v| m.max(v.abs()));
            assert!(peak > 0.05 && peak < 1.5, "{synth:?} peak {peak}");
            // The wrap (last → first) should be no bigger a jump than typical
            // neighbouring samples.
            let jump = (s[0][0] - s[s.len() - 1][0]).abs();
            let typical = s.windows(2).map(|w| (w[1][0] - w[0][0]).abs()).fold(0.0f32, f32::max);
            assert!(jump <= typical + 1e-3, "{synth:?} wrap jump {jump} > max step {typical}");
        }
    }
}
